<?php
declare(strict_types=1);require_once dirname(__DIR__,2).'/src/helpers.php';$user=require_admin();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='add'){$name=trim($_POST['name']??'');$rate=filter_var($_POST['rate']??null,FILTER_VALIDATE_FLOAT);$gst=filter_var($_POST['igst_rate']??null,FILTER_VALIDATE_FLOAT);if($name===''||$rate===false||$rate<0||$gst===false||$gst<0){$error='Enter product name, Rate, and IGST.';}else{try{db()->prepare('INSERT INTO products (name,rate,igst_rate) VALUES (?,?,?)')->execute([$name,$rate,$gst]);}catch(PDOException){$error='That product already exists.';}}}elseif($action==='toggle'&&$id){db()->prepare('UPDATE products SET active=1-active WHERE id=?')->execute([$id]);}if($error==='')redirect('products.php');}
$products=db()->query('SELECT * FROM products ORDER BY active DESC,name')->fetchAll();page_start('Products',$user);?>
<form method="post" class="card"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><h2>Add product</h2><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><label>Product name<input name="name" required></label><label>Rate (GST exclusive)<input name="rate" type="number" min="0" step="0.01" required></label><label>IGST %<input name="igst_rate" type="number" min="0" step="0.01" required></label><button>Add product</button></form>
<?php foreach($products as $p):?><article class="card"><strong><?=e($p['name'])?></strong><p>Rate ₹<?=number_format((float)$p['rate'],2)?> · IGST <?=e((string)$p['igst_rate'])?>% · <?=$p['active']?'Active':'Inactive'?></p><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="secondary"><?=$p['active']?'Deactivate':'Activate'?></button></form></article><?php endforeach;?><?php page_end($user);?>
